"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73244"],{16830(e){e.exports=JSON.parse('{"id":"FIN-1163","slug":"price-discovery","term":"Price Discovery","also_known_as":[],"difficulty":"Advanced","definition":"Price discovery is the process by which buyers and sellers interacting in a market determine an asset\'s price, as new information and changing views are reflected in trades.","explanation":["Markets bring together many participants with different information, opinions and needs. As they place buy and sell orders, prices move to the level at which supply and demand balance. This price reflects the market\'s combined assessment of the asset\'s value at that moment.","For example, when a company releases unexpectedly strong results, buyers rush in and sellers raise their asking prices. Within minutes, the share price adjusts upwards to reflect the new information.","Efficient price discovery requires transparent markets, active trading, many participants and access to information. Futures markets often play a key role in price discovery for commodities, since many traders express their views there.","Price discovery can be weaker in illiquid markets, private markets and markets with limited transparency, where prices may be set less often and may not reflect all available information. Good price discovery benefits the wider economy by helping capital flow to its most valued uses."],"note":"","total":1500,"prev":{"slug":"price-ceiling","term":"Price Ceiling"},"next":{"slug":"price-discrimination","term":"Price Discrimination"}}')}}]);